import{_ as i,C as o,o as l,c as n,a4 as e,E as s}from"./chunks/framework.DAD9IEko.js";const _=JSON.parse('{"title":"SYS-07 电源-电控联合闭环系统设计","description":"","frontmatter":{"date":"2026-06-11T00:00:00.000Z","section":"电机控制","chapter":"advanced","chapterTitle":"进阶专题","chapterOrder":30,"category":"进阶专题","source":"motor","visibility":"public","title":"SYS-07 电源-电控联合闭环系统设计","tags":["motor-control"],"status":"learning","summary":"> **状态**: reviewed > **目标**: 把电源与电控从“两个章节”连接成一个可调试、可验证、可回传的系统闭环。","navGroup":"实践与验证","navGroupOrder":40},"headers":[],"relativePath":"content/motor/advanced/system-methodology/SYS-07-Power-Control-Closed-Loop.md","filePath":"content/motor/advanced/system-methodology/SYS-07-Power-Control-Closed-Loop.md","lastUpdated":1783181958000}'),r={name:"content/motor/advanced/system-methodology/SYS-07-Power-Control-Closed-Loop.md"};function d(h,a,p,c,u,E){const t=o("MermaidDiagram");return l(),n("div",null,[a[0]||(a[0]=e('<h1 id="sys-07-电源-电控联合闭环系统设计" tabindex="-1">SYS-07 电源-电控联合闭环系统设计 <a class="header-anchor" href="#sys-07-电源-电控联合闭环系统设计" aria-label="Permalink to &quot;SYS-07 电源-电控联合闭环系统设计&quot;">​</a></h1><blockquote><p><strong>状态</strong>: reviewed<br><strong>目标</strong>: 把电源与电控从“两个章节”连接成一个可调试、可验证、可回传的系统闭环。</p></blockquote><p><strong>模块编号：</strong> SYS-07<br><strong>模块名称：</strong> 电源-电控联合闭环系统设计<br><strong>文档版本：</strong> v1.1<br><strong>前置知识：</strong> PP-11 Boost PFC 与母线动态、ALG-03 PI 电流调节器、SYS-06 系统测试与验证<br><strong>难度等级：</strong></p><hr><h2 id="_1-核心摘要" tabindex="-1">1. 核心摘要 <a class="header-anchor" href="#_1-核心摘要" aria-label="Permalink to &quot;1.  核心摘要&quot;">​</a></h2><p><strong>一句话：</strong> 电源和电控不能作为两个孤立模块调试：电源侧决定母线质量、保护边界和功率上限，电控侧决定电流、转矩和负载动态，两者必须通过统一配置、统一 trace、统一故障流和统一验证报告形成闭环。</p><p><strong>认知挂钩：</strong> 电机系统像一条能量流水线。PFC、DC/DC、逆变器、传感器和 FOC 都在同一条线上工作。任何一段只做“本模块 OK”的局部验证，都可能在整机联调时失效。真正可发布的知识库不是只讲原理，而是能把理论、仿真、固件、实测数据和问题回传连起来。</p><p><strong>核心问题链：</strong></p>',8)),s(t,{code:"flowchart%20TD%0A%20%20A%5B%22%E7%9F%A5%E8%AF%86%E6%A8%A1%E5%9D%97%E7%BB%99%E5%87%BA%E7%90%86%E8%AE%BA%E5%92%8C%E9%85%8D%E7%BD%AE%22%5D%20--%3E%20B%5B%22%E4%BB%BF%E7%9C%9F%E9%AA%8C%E8%AF%81%E8%BE%B9%E7%95%8C%22%5D%0A%20%20B%20--%3E%20C%5B%22lxfoc%20%E5%9B%BA%E4%BB%B6%E5%AF%BC%E5%85%A5%E9%85%8D%E7%BD%AE%22%5D%0A%20%20C%20--%3E%20D%5B%22%E7%A1%AC%E4%BB%B6%E8%BF%90%E8%A1%8C%E5%B9%B6%E8%BE%93%E5%87%BA%20trace%22%5D%0A%20%20D%20--%3E%20E%5B%22%E7%9F%A5%E8%AF%86%E5%BA%93%E7%94%9F%E6%88%90%E8%AF%AF%E5%B7%AE%E6%8A%A5%E5%91%8A%22%5D%0A%20%20E%20--%3E%20F%5B%22%E9%97%AE%E9%A2%98%E5%9B%9E%E4%BC%A0%E5%88%B0%E6%A8%A1%E5%9D%97%E3%80%81%E9%85%8D%E7%BD%AE%E6%88%96%E4%BB%A3%E7%A0%81%22%5D%0A%20%20F%20--%3E%20A%0A"}),a[1]||(a[1]=e('<hr><h2 id="_2-问题引入" tabindex="-1">2. 问题引入 <a class="header-anchor" href="#_2-问题引入" aria-label="Permalink to &quot;2.  问题引入&quot;">​</a></h2><h3 id="工程师的真实困惑" tabindex="-1">工程师的真实困惑 <a class="header-anchor" href="#工程师的真实困惑" aria-label="Permalink to &quot;工程师的真实困惑&quot;">​</a></h3><blockquote><p><strong>场景 1：电源工程师说母线正常，电控工程师说电流环异常</strong><br> 空载测得母线稳定，但电机加速时 <code>vbus</code> 短暂跌落，FOC 电压限幅触发。电源侧只看稳态值，电控侧只看 dq 电流误差，双方都缺少统一 trace。</p></blockquote><blockquote><p><strong>场景 2：仿真通过，硬件一跑就保护</strong><br> 仿真使用理想母线和理想采样，硬件中存在母线纹波、采样延迟、死区、限流和温度保护。没有把硬件限制写进 manifest，导致仿真结论无法对应实测。</p></blockquote><blockquote><p><strong>场景 3：修复问题后知识库没有更新</strong><br> 工程调试中发现欠压迟滞、弱磁边界或电流限幅设置不合理，固件临时改好了，但文档、配置包和验证报告没有同步，下一次复现仍然踩同一个问题。</p></blockquote><h3 id="核心问题" tabindex="-1">核心问题 <a class="header-anchor" href="#核心问题" aria-label="Permalink to &quot;核心问题&quot;">​</a></h3><p>为什么需要“电源-电控联合闭环”，而不是分别把电源和 FOC 调好？</p><p><strong>答案：</strong> 因为实际系统的约束跨越模块边界。母线动态影响 FOC，FOC 负载阶跃反过来影响电源；保护和数据记录如果不统一，就无法判断问题来源，也无法把经验沉淀回知识库。</p><h3 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h3><p>读完本模块，你将能够：</p><p>定义电源、逆变器、传感器、FOC 和知识库之间的系统边界<br> 制定从电源前级到闭环运行的调试顺序<br> 设计统一实验 manifest 和 trace 字段<br> 建立故障记录、分析和回传流程<br> 判断模块是否只能标为 <code>reviewed</code>，还是可以升级为 <code>verified</code></p><hr><h2 id="_3-直观理解" tabindex="-1">3. 直观理解 <a class="header-anchor" href="#_3-直观理解" aria-label="Permalink to &quot;3.  直观理解&quot;">​</a></h2><h3 id="_3-1-系统边界" tabindex="-1">3.1 系统边界 <a class="header-anchor" href="#_3-1-系统边界" aria-label="Permalink to &quot;3.1 系统边界&quot;">​</a></h3><p>完整系统按功率流可以分为：</p>',16)),s(t,{code:"flowchart%20LR%0A%20%20Grid%5B%22AC%20input%20%2F%20DC%20source%22%5D%20--%3E%20PFC%5B%22PFC%20or%20rectifier%22%5D%0A%20%20PFC%20--%3E%20DCDC%5B%22DC%2FDC%20or%20bus%20stage%22%5D%0A%20%20DCDC%20--%3E%20INV%5B%22Inverter%22%5D%0A%20%20INV%20--%3E%20Motor%5B%22PMSM%20%2F%20load%22%5D%0A%20%20Motor%20--%3E%20Sense%5B%22Current%2Fposition%20sensing%22%5D%0A%20%20Sense%20--%3E%20CTRL%5B%22lxfoc%20control%22%5D%0A%20%20CTRL%20--%3E%20INV%0A"}),a[2]||(a[2]=e(`<p>电源侧决定母线质量，电控侧决定电机电流和转矩。两者必须共享母线电压、保护状态、功率限制和故障策略。</p><h3 id="_3-2-闭环不是单个控制环" tabindex="-1">3.2 闭环不是单个控制环 <a class="header-anchor" href="#_3-2-闭环不是单个控制环" aria-label="Permalink to &quot;3.2 闭环不是单个控制环&quot;">​</a></h3><p>这里的“闭环”不是单指 PI 电流环，而是知识闭环：</p><ol><li>文档给出理论和参数边界。</li><li>仿真验证理论是否能复现。</li><li>固件按同一配置运行。</li><li>硬件回传标准 trace。</li><li>知识库生成报告并更新证据状态。</li></ol><p>如果缺少任意一环，系统仍然可以运行，但知识库不能声称对应模块已经实测验证。</p><hr><h2 id="_4-技术原理" tabindex="-1">4. 技术原理 <a class="header-anchor" href="#_4-技术原理" aria-label="Permalink to &quot;4.  技术原理&quot;">​</a></h2><h3 id="_4-1-调试顺序" tabindex="-1">4.1 调试顺序 <a class="header-anchor" href="#_4-1-调试顺序" aria-label="Permalink to &quot;4.1 调试顺序&quot;">​</a></h3><p>推荐顺序如下：</p><ol><li>单独验证电源前级：空载、假负载、限流、保护。</li><li>单独验证逆变器：不开电机时检查 PWM、死区、采样。</li><li>低压低流验证 lxfoc：V/F、I/F、电流环。</li><li>接入母线动态：记录 <code>vbus_V</code> 并验证电压限幅。</li><li>闭环运行：导入 trace 到知识库生成误差报告。</li></ol><p>这个顺序的目的不是拖慢进度，而是让每个故障都有明确归属。跳过前级验证直接闭环运行，问题会混在一起，难以复盘。</p><h3 id="_4-2-统一实验-manifest" tabindex="-1">4.2 统一实验 manifest <a class="header-anchor" href="#_4-2-统一实验-manifest" aria-label="Permalink to &quot;4.2 统一实验 manifest&quot;">​</a></h3><p>每次实验必须绑定：</p><ul><li><code>doc_id</code>: 知识模块来源。</li><li><code>experiment_id</code>: 仿真、固件、实测数据的共同 ID。</li><li><code>config_schema_version</code>: lxfoc 配置版本。</li><li><code>trace_schema_version</code>: 回传数据版本。</li><li><code>hardware_limits</code>: 电压、电流、温度、转速限制。</li></ul><p>示例：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;doc_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;power-path/PP-11-Boost-PFC-Bus-Dynamics&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;experiment_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PP11-vbus-step-001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;config_schema_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;trace_schema_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;hardware_limits&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;vbus_min_V&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;vbus_max_V&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">420</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;phase_current_max_A&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;temperature_max_C&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">85</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="_4-3-标准-trace" tabindex="-1">4.3 标准 trace <a class="header-anchor" href="#_4-3-标准-trace" aria-label="Permalink to &quot;4.3 标准 trace&quot;">​</a></h3><p>跨电源和电控的 trace 至少应包含：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>time_s,</span></span>
<span class="line"><span>vbus_V,</span></span>
<span class="line"><span>id_A, iq_A, id_ref_A, iq_ref_A,</span></span>
<span class="line"><span>ud_V, uq_V,</span></span>
<span class="line"><span>duty_a, duty_b, duty_c,</span></span>
<span class="line"><span>speed_hz,</span></span>
<span class="line"><span>fault_flags</span></span></code></pre></div><p>如果验证对象涉及 PFC 或三电平母线，还应增加：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vac_a_V, vac_b_V, vac_c_V,</span></span>
<span class="line"><span>iac_a_A, iac_b_A, iac_c_A,</span></span>
<span class="line"><span>vdc_upper_V, vdc_lower_V</span></span></code></pre></div><h3 id="_4-4-故障流" tabindex="-1">4.4 故障流 <a class="header-anchor" href="#_4-4-故障流" aria-label="Permalink to &quot;4.4 故障流&quot;">​</a></h3><p>故障不是只在硬件里处理，也要回传给知识库：</p><div class="kb-table-scroll"><table><thead><tr><th>故障</th><th>必须记录</th><th>分析动作</th></tr></thead><tbody><tr><td>欠压</td><td><code>vbus_V</code>, <code>fault_flags</code></td><td>判断是否由负载阶跃或输入跌落导致</td></tr><tr><td>过流</td><td>三相电流、dq 电流</td><td>判断采样、PI、负载、短路</td></tr><tr><td>过调制</td><td>duty、ud/uq、vbus</td><td>判断母线不足或弱磁不足</td></tr><tr><td>观测器失锁</td><td>估计角、传感器角、速度</td><td>判断适用速度范围</td></tr></tbody></table></div><hr><h2 id="_5-交叉视角" tabindex="-1">5. 交叉视角 <a class="header-anchor" href="#_5-交叉视角" aria-label="Permalink to &quot;5.  交叉视角&quot;">​</a></h2><h3 id="_5-1-与知识库状态的关系" tabindex="-1">5.1 与知识库状态的关系 <a class="header-anchor" href="#_5-1-与知识库状态的关系" aria-label="Permalink to &quot;5.1 与知识库状态的关系&quot;">​</a></h3><p>知识模块的状态必须与证据一致：</p><ul><li><code>draft</code>: 内容仍在整理，未完成基本交叉检查。</li><li><code>reviewed</code>: 理论、仿真或代码证据已通过审查，但没有完整硬件闭环证据。</li><li><code>verified</code>: 有可复现硬件数据、原始采样、校准信息、审查人和误差报告。</li></ul><p>未完成实测的模块必须显示为 <code>reviewed</code> 或 <code>draft</code>，不能标为 <code>verified</code>。</p><h3 id="_5-2-与-lxfoc-的关系" tabindex="-1">5.2 与 lxfoc 的关系 <a class="header-anchor" href="#_5-2-与-lxfoc-的关系" aria-label="Permalink to &quot;5.2 与 lxfoc 的关系&quot;">​</a></h3><p>lxfoc 应提供标准配置导入和 trace 导出能力。知识库不应只写“调某个参数”，而应能明确：</p><ul><li>参数来自哪个 <code>doc_id</code>。</li><li>固件使用哪个配置版本。</li><li>trace 字段是否足以验证该模块。</li><li>报告是否能复现实验结论。</li></ul><h3 id="_5-3-与系统测试的关系" tabindex="-1">5.3 与系统测试的关系 <a class="header-anchor" href="#_5-3-与系统测试的关系" aria-label="Permalink to &quot;5.3 与系统测试的关系&quot;">​</a></h3><p>SYS-06 关注测试和验证方法，本模块关注电源与电控跨域闭环。两者的交集是：所有测试都必须能回答“这个现象是电源侧、电控侧、采样侧、保护侧还是配置侧造成的”。</p><hr><h2 id="_6-工程案例" tabindex="-1">6. 工程案例 <a class="header-anchor" href="#_6-工程案例" aria-label="Permalink to &quot;6.  工程案例&quot;">​</a></h2><h3 id="案例-母线跌落导致电流环限幅" tabindex="-1">案例：母线跌落导致电流环限幅 <a class="header-anchor" href="#案例-母线跌落导致电流环限幅" aria-label="Permalink to &quot;案例：母线跌落导致电流环限幅&quot;">​</a></h3><p><strong>现象：</strong></p><p>电机从 1000 rpm 加速到 2500 rpm，<code>iq_ref</code> 阶跃。实测 <code>iq_A</code> 跟踪变差，随后 <code>fault_flags</code> 出现欠压预警。</p><p><strong>闭环排查：</strong></p><div class="kb-table-scroll"><table><thead><tr><th>步骤</th><th>检查对象</th><th>结论判断</th></tr></thead><tbody><tr><td>1</td><td><code>vbus_V</code></td><td>是否在 <code>iq_ref</code> 阶跃后跌落</td></tr><tr><td>2</td><td><code>ud_V/uq_V</code></td><td>是否接近实时电压限幅</td></tr><tr><td>3</td><td><code>duty_a/b/c</code></td><td>是否进入过调制或接近饱和</td></tr><tr><td>4</td><td><code>fault_flags</code></td><td>欠压是否先于电流误差恶化</td></tr><tr><td>5</td><td>manifest</td><td>硬件限流和母线阈值是否与固件一致</td></tr></tbody></table></div><p><strong>可能结论：</strong></p><p>如果 <code>vbus_V</code> 先跌落，随后 <code>uq_V</code> 顶到限幅，最后 <code>iq_A</code> 误差增大，则优先处理 PFC 母线动态或加速功率限制，而不是直接调大电流环 PI。</p><h3 id="案例输出物" tabindex="-1">案例输出物 <a class="header-anchor" href="#案例输出物" aria-label="Permalink to &quot;案例输出物&quot;">​</a></h3><p>一次合格的闭环验证至少产生：</p><ul><li>实验 manifest。</li><li>固件配置快照。</li><li>标准 trace CSV。</li><li>自动生成的误差报告。</li><li>proof 文件中的证据引用。</li></ul><hr><h2 id="_7-实践练习" tabindex="-1">7. 实践练习 <a class="header-anchor" href="#_7-实践练习" aria-label="Permalink to &quot;7.  实践练习&quot;">​</a></h2><h3 id="练习-1-故障归因" tabindex="-1">练习 1：故障归因 <a class="header-anchor" href="#练习-1-故障归因" aria-label="Permalink to &quot;练习 1：故障归因&quot;">​</a></h3><p>闭环运行中 <code>iq</code> 跟踪误差增大，同时 <code>vbus_V</code> 明显跌落。第一步应检查什么？</p><p><strong>参考答案：</strong></p><p>先检查 <code>ud/uq</code> 是否接近实时电压限幅，以及 duty 是否接近饱和。如果电压已经受限，优先分析母线动态、功率限制和弱磁策略，而不是直接调 PI。</p><h3 id="练习-2-状态判定" tabindex="-1">练习 2：状态判定 <a class="header-anchor" href="#练习-2-状态判定" aria-label="Permalink to &quot;练习 2：状态判定&quot;">​</a></h3><p>某模块有仿真报告和代码审查，但没有硬件原始数据、校准信息和审查人。它可以标为 <code>verified</code> 吗？</p><p><strong>参考答案：</strong></p><p>不可以。它最多是 <code>reviewed</code>。<code>verified</code> 必须有可复现硬件数据、原始采样、校准信息、审查人和误差报告。</p><h3 id="练习-3-manifest-字段" tabindex="-1">练习 3：Manifest 字段 <a class="header-anchor" href="#练习-3-manifest-字段" aria-label="Permalink to &quot;练习 3：Manifest 字段&quot;">​</a></h3><p>为什么实验 manifest 必须包含 <code>doc_id</code> 和 <code>experiment_id</code>？</p><p><strong>参考答案：</strong></p><p><code>doc_id</code> 说明实验验证哪个知识模块，<code>experiment_id</code> 把仿真、固件、实测数据和报告绑定到同一次实验，便于复现和追踪。</p><h3 id="练习-4-trace-字段" tabindex="-1">练习 4：Trace 字段 <a class="header-anchor" href="#练习-4-trace-字段" aria-label="Permalink to &quot;练习 4：Trace 字段&quot;">​</a></h3><p>验证母线动态时，为什么只记录 dq 电流不够？</p><p><strong>参考答案：</strong></p><p>dq 电流只能说明控制结果，无法判断电压裕量和故障来源。必须记录 <code>vbus_V</code>、<code>ud/uq</code>、duty 和 <code>fault_flags</code>，才能判断是否由母线跌落、限幅或保护触发导致。</p><hr><h2 id="_8-验收标准" tabindex="-1">8. 验收标准 <a class="header-anchor" href="#_8-验收标准" aria-label="Permalink to &quot;8.  验收标准&quot;">​</a></h2><ul><li>知识库能导出 lxfoc 配置包。</li><li>lxfoc 能输出标准 trace。</li><li>知识库能生成理论/仿真/实测误差报告。</li><li>未完成实测的模块必须显示为 <code>reviewed</code> 或 <code>draft</code>，不能标为 <code>verified</code>。</li></ul><p>本模块的 proof 文件位于 <code>_proofs/advanced/system-methodology/SYS-07-Power-Control-Closed-Loop.module-proof.yaml</code>。</p>`,69))])}const b=i(r,[["render",d]]);export{_ as __pageData,b as default};
